          <tr><td style="font-size:20px;font-weight:600;padding-bottom:24px;">Notely</td></tr>
          <tr><td style="font-size:15px;line-height:1.6;">${bodyHtml}</td></tr>
        </table>
      </td></tr>
    </table>
  </body>
</html>`;
}

